from pathlib import Path

def publish_azure_article(output):
    target = Path(output)/'pricing'/'azure-virtual-server'
    target.mkdir(parents=True, exist_ok=True)
    (target/'index.html').write_text(ARTICLE, encoding='utf-8')
    (target/'page.css').write_text(STYLES, encoding='utf-8')
    (target/'sources.json').write_text(SOURCES, encoding='utf-8')
    return ('/pricing/azure-virtual-server/', TIMESTAMP)

